+/// behind the no-op `--enable-flash-late-interaction`.
+fn is_bool_flag(arg: &clap::Arg) -> bool {
+    arg.get_num_args() == Some((0..=1).into())
+        && arg.get_value_parser().type_id() == ValueParser::bool().type_id()
